#include <print>

int main() {
    int age = 15;
    double score = 92.5;

    std::println("age   的值  : {}", age);
    std::println("age   的地址: {:p}", &age);      // 跑两次这里的号不一样，程序被放到哪儿是系统临场定的
    std::println("score 的地址: {:p}", &score);    // 0x 打头是 16 进制，编号这样写短一半

    int age2 = age;
    std::println("age2 的地址: {:p}", &age2);
    std::println("同一个柜子吗？{}", &age == &age2);

    age2 = 16;
    std::println("age = {}, age2 = {}", age, age2);
    return 0;
}

